import React from 'react';
import { Star } from '@hexa-ui/icons';
import { fireEvent, render, screen } from '@testing-library/react';
import { Badge } from '../..';

const mockedOnClick = jest.fn();

describe('Badge', () => {
  test('should render badge counter component without crashing', () => {
    render(<Badge.Counter />);
    expect(screen.getByText('0')).toBeInTheDocument();
  });

  test('should render badge counter component with custom counter label', () => {
    render(<Badge.Counter counterLabel="99+" />);
    expect(screen.getByText('99+')).toBeInTheDocument();
  });
});

describe('BadgeStatus', () => {
  it('should render without crashing', () => {
    render(<Badge.Status />);
    const badgeComponent = screen.getByText('Label');
    expect(badgeComponent).toBeInTheDocument();
  });

  it('should render type interactive without crashing', () => {
    render(<Badge.Status label="interactive" type="interactive" />);
    const badgeComponent = screen.getByText('interactive');
    expect(badgeComponent).toBeInTheDocument();
  });

  it('should call onClick function when type is interactive', () => {
    render(<Badge.Status label="interactive" type="interactive" onClick={mockedOnClick} />);
    const badgeComponent = screen.getByText('interactive');
    fireEvent.click(badgeComponent);
    expect(mockedOnClick).toHaveBeenCalled();
  });

  it('should render when disabled is true', () => {
    render(<Badge.Status label="disabled" type="interactive" disabled onClick={mockedOnClick} />);
    const badgeComponent = screen.getByText('disabled');
    fireEvent.click(badgeComponent);
    expect(mockedOnClick).not.toHaveBeenCalledWith(mockedOnClick);
  });
});

describe('BadgeCategory', () => {
  it('should render without crashing', () => {
    render(<Badge.Category />);
    const badgeComponent = screen.getByText('Label');
    expect(badgeComponent).toBeInTheDocument();
  });

  it('should render type interactive without crashing', () => {
    render(<Badge.Category label="interactive" type="interactive" />);
    const badgeComponent = screen.getByText('interactive');
    expect(badgeComponent).toBeInTheDocument();
  });

  it('should call onClick function when type is interactive', () => {
    render(<Badge.Category label="interactive" type="interactive" onClick={mockedOnClick} />);
    const badgeComponent = screen.getByText('interactive');
    fireEvent.click(badgeComponent);
    expect(mockedOnClick).toHaveBeenCalled();
  });

  it('should render when disabled is true', () => {
    render(<Badge.Category label="disabled" type="interactive" disabled onClick={mockedOnClick} />);
    const badgeComponent = screen.getByText('disabled');
    fireEvent.click(badgeComponent);
    expect(mockedOnClick).not.toHaveBeenCalledWith(mockedOnClick);
  });

  it('should render with custom icon', () => {
    render(<Badge.Category label="Star" icon={Star} />);
    const badgeComponent = screen.getByTestId('Star');
    expect(badgeComponent).toBeInTheDocument();
  });
});
